  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C37"],
      "claim": "Bumetanide absolute bioavailability was 0.86 ± 0.13 in normal subjects after a 1 mg oral tablet versus IV, well above the 20% threshold."
    },
    {
      "card_ids": ["C40"],
      "claim": "Mosliciguat absolute bioavailability was 23.1% in healthy male volunteers after a 1000 µg oral solution versus IV, supporting high bioavailability."
    },
    {
      "card_ids": ["C34"],
      "claim": "Azosemide absolute bioavailability was approximately 20.4% in healthy fasting humans, supporting high bioavailability despite a separate methodologically limited low estimate."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": ["C41"],
  "decision_summary": "All condition-matched numeric absolute bioavailability records across transferred evidence are at or above 20%, with most well above the threshold; the only low estimate is methodologically limited and contradicted by a direct absolute measurement.",
  "evidence_gaps": [
    "Azosemide has a conflicting low estimate (C41) based on urinary excretion across different patients without serum AUC comparison.",
    "Y-700 evidence is qualitative (C36) and not threshold-specific.",
    "GDC-0810 evidence is PBPK-predicted without clinical data (C26)."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C37", "C40", "C34"],
  "revision_action": "initial",
  "supportive_card_ids": ["C37", "C40", "C34"]
}

